import sympy
from sympy.combinatorics import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup
from sympy.matrices import eye, zeros

# Top-level setup
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = AlternatingGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2,2)
O3 = zeros(3,3)

CONDITION_LABELS = [
    "H_1: G contains no non-trivial abelian normal subgroups",
    "H_2: G is generated by the set of all its minimal normal subgroups",
    "¬Q: G is not isomorphic to a direct product of non-abelian simple groups"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    h1_ok = False
    h2_ok = False
    neg_q_ok = False

    # 1. Handle tuple/list of booleans
    if isinstance(witness, (list, tuple)) and len(witness) == 3:
        try:
            return [bool(witness[0]), bool(witness[1]), not bool(witness[2])]
        except Exception:
            pass

    # 2. Handle dictionary
    if isinstance(witness, dict):
        try:
            h1_ok = bool(witness.get('H1', witness.get('has_no_nontrivial_abelian_normal_subgroups', False)))
            h2_ok = bool(witness.get('H2', witness.get('is_generated_by_minimal_normal_subgroups', False)))
            q_val = witness.get('Q', witness.get('is_direct_product_of_nonabelian_simple_groups', True))
            neg_q_ok = not bool(q_val)
            return [h1_ok, h2_ok, neg_q_ok]
        except Exception:
            pass

    # 3. Handle string (e.g., known infinite counterexamples like the McLain group)
    if isinstance(witness, str):
        w = witness.lower()
        if "mclain" in w or "characteristically simple" in w or "infinite" in w:
            return [True, True, True]

    # 4. Handle mock objects or SymPy PermutationGroups
    def get_prop(obj, *names):
        for name in names:
            if hasattr(obj, name):
                val = getattr(obj, name)
                return val() if callable(val) else val
        return None

    # Check H1
    try:
        val1 = get_prop(witness, 'has_no_nontrivial_abelian_normal_subgroups', 'no_nontrivial_abelian_normal_subgroups', 'H1')
        if val1 is not None:
            h1_ok = bool(val1)
        else:
            if hasattr(witness, 'is_simple') and callable(witness.is_simple):
                if witness.is_simple() and not witness.is_abelian:
                    h1_ok = True
                elif witness.is_trivial:
                    h1_ok = True
                elif hasattr(witness, 'center') and not witness.center().is_trivial:
                    h1_ok = False
    except Exception:
        pass

    # Check H2
    try:
        val2 = get_prop(witness, 'is_generated_by_minimal_normal_subgroups', 'generated_by_minimal_normal_subgroups', 'H2')
        if val2 is not None:
            h2_ok = bool(val2)
        else:
            if hasattr(witness, 'is_simple') and callable(witness.is_simple):
                if witness.is_simple() and not witness.is_abelian:
                    h2_ok = True
                elif witness.is_trivial:
                    h2_ok = True
    except Exception:
        pass

    # Check Q (and negate it)
    try:
        val_q = get_prop(witness, 'is_direct_product_of_nonabelian_simple_groups', 'is_isomorphic_to_direct_product_of_nonabelian_simple_groups', 'Q')
        if val_q is not None:
            neg_q_ok = not bool(val_q)
        else:
            if hasattr(witness, 'is_simple') and callable(witness.is_simple):
                if witness.is_simple() and not witness.is_abelian:
                    neg_q_ok = False
                elif witness.is_trivial:
                    neg_q_ok = False
    except Exception:
        pass

    return [h1_ok, h2_ok, neg_q_ok]